/** Cria no banco vazio o que o sistema precisa. Pode rodar quantas vezes for preciso. */
public final class Schema {
    private Schema() {}

    public static void create(Database db) {
        db.transaction(() -> {
            try (Statement st = db.connection().createStatement()) {
